function canvasTex(w,hh,draw){var c=document.createElement("canvas");c.width=w;c.height=hh;draw(c.getContext("2d"),w,hh);var t=new T.CanvasTexture(c);t.encoding=T.sRGBEncoding;t.anisotropy=4;return t;}
