/* ---------- layout: rooms grow with bots, floors grow with rooms ---------- */
function layoutRoom(room){var t=TYPES[room.type]||TYPES.team,n=room.bots.length,L={type:room.type,stations:[],rest:[]};
 if(room.type==="hq"){var per=Math.max(2,Math.ceil(n/2)),len=Math.max(4,per*1.7);L.W=Math.max(t.minW,len+4.5+t.zone);L.table={x:-L.W/2+2.2+len/2,z:-.6,len:len};
  for(var i=0;i<n;i++){var side=i%2?1:-1,k=Math.floor(i/2);L.stations.push({x:L.table.x-len/2+.85+k*1.7,z:L.table.z+side*1.55,side:side});}L.zoneX=-L.W/2+2.2+len+1.2;}
 else{var cols=Math.max(2,Math.ceil(n/2));L.W=Math.max(t.minW,cols*PITCH+2.6+t.zone);for(var j=0;j<n;j++){var c=j%cols,r=Math.floor(j/cols);L.stations.push({x:-L.W/2+2.8+c*PITCH,z:r?1.6:-3.2});}L.zoneX=-L.W/2+2.4+cols*PITCH;}
 L.zoneW=L.W/2-L.zoneX;var cx=L.zoneX+L.zoneW/2;L.restC={x:cx,z:3};L.rest=[[cx-1.2,4.4],[cx,4.4],[cx+1.2,4.4],[cx-1.2,1.6],[cx,1.6],[cx+1.2,1.6]];return L;}
function layoutFloor(f){var x=0,rooms=f.rooms.map(function(r){var L=layoutRoom(r);L.cx=x+L.W/2;x+=L.W+GAP;return L;});var W=Math.max(8,x-GAP);rooms.forEach(function(L){L.cx-=W/2;});return {W:W,rooms:rooms};}

