 function reply(b,text){var t=String(text||"").toLowerCase(),role=(ROLES[b.role]||{}).label||"bot";
  if(/status|what are you|doing/.test(t))return {text:"I am "+b.status+": "+b.task+"."};
  if(/summar|report|recap/.test(t)){done[b.name]=(done[b.name]||2);return {text:"Summary: I closed "+done[b.name]+" tasks today. Now: "+b.task.toLowerCase()+"."};}
  if(/^(pause|stop|hold)/.test(t))return {text:"Pausing now. Send resume when you want me back.",status:"resting",task:"Paused by you"};
  if(/^(resume|start|continue|go)/.test(t))return {text:"Back to work: "+b.task.toLowerCase()+".",status:"working",task:(b.tasks||[b.task])[0]};
  if(/help|what can you/.test(t))return {text:"As "+role+" I can: "+(b.tasks||[]).slice(0,3).join(", ").toLowerCase()+". Give me a task."};
  return {text:"On it. New task: "+cap(text)+".",status:"working",task:cap(text)};}
 var TOOLS={research:[["web_search","browser"],["web_extract","browser"],["graph_search","connector"]],writer:[["write_file","code"],["draft_doc","connector"]],coder:[["execute_code","code"],["terminal","terminal"],["mcp:github.create_pr","mcp"]],analyst:[["execute_code","code"],["query_dataverse","connector"]],designer:[["image_generate","api"]],ops:[["terminal","terminal"],["flow:Create ticket","flow"]],sales:[["crm_lookup","connector"]],planner:[["delegate_task","api"],["skills_list","skill"]],media:[["tts","api"]],
  ae:[["crm_lookup","connector"]],specialist:[["build_business_case","flow"]],partner:[["partner_match","connector"]],se:[["mcp:demo_env.create","mcp"]],csa:[["mcp:azure.policy_check","mcp"]],csam:[["get_adoption_metrics","connector"]],fde:[["execute_code","code"],["terminal","terminal"]]};
 var tc=0,orchT=0;
